const { test, expect } = require("@playwright/test");

// Guards the demo's replayable outbound example: the northstar usage_alert bounce
// (recipient ops@northstar.example, SendGrid, provider id sg-demo-usage-001). It drives the
// real library path: OperatorLive confirm_replay -> DestructiveAction.authorize ->
// Mailglass.Webhook.Replay.execute. IDs are regenerated by every reset, so the delivery is
// located by seeded content, never by UUID.

test.describe("demo outbound replay", () => {
  test.beforeEach(async ({ request }) => {
    const response = await request.post("/demo/evidence/reset", {
      headers: {
        "x-mailglass-demo-reset-token": process.env.DEMO_EVIDENCE_RESET_TOKEN || "",
      },
    });
    expect(response.ok()).toBeTruthy();
  });

  test("outbound replay from the demo completes and records a new event", async ({ page }) => {
    // Locate the usage_alert bounce. The desktop table row carries the status text "Bounced";
    // the mobile card variant does not, so exactly one row matches.
    await page.goto(
      `/demo/login?return_to=${encodeURIComponent("/ops/mail?tenant_id=northstar&view=deliveries")}`,
    );
    await page.locator("[data-phx-main].phx-connected").waitFor();
    await expect(page.getByTestId("operator-deliveries-list-card")).toBeVisible();
    const target = page
      .getByTestId("operator-delivery-row")
      .filter({ hasText: "ops@northstar.example" })
      .filter({ hasText: "email usage reached 85%" })
      .filter({ hasText: "Bounced" });
    await expect(target).toHaveCount(1);
    const deliveryId = await target.getAttribute("phx-value-id");
    expect(deliveryId).toBeTruthy();

    const returnTo = encodeURIComponent(
      `/ops/mail?tenant_id=northstar&delivery_id=${deliveryId}&full=1`,
    );
    await page.goto(`/demo/login?return_to=${returnTo}`);
    // Clicking a phx-click before the socket joins is a race; wait for the connected LiveView.
    await page.locator("[data-phx-main].phx-connected").waitFor();
    await expect(page.getByTestId("operator-detail-header")).toBeVisible();

    const succeeded = page
      .getByTestId("operator-timeline-event")
      .filter({ hasText: "Replay audit · completed" });
    const before = await succeeded.count();

    await page.getByTestId("operator-replay-open").click();
    await expect(page.getByTestId("operator-replay-modal")).toBeVisible();
    const unavailable = page.getByTestId("operator-replay-evidence-unavailable");
    expect(
      await unavailable.count(),
      "replay modal shows evidence unavailable: the seeded usage_alert webhook linkage in demo_data.ex is broken",
    ).toBe(0);
    await expect(page.getByTestId("operator-replay-reviewed-target")).toBeVisible();

    await page.getByTestId("operator-replay-confirm").click();

    const flashText = async () =>
      (await page.locator("[role=alert], [data-testid*=flash]").allInnerTexts()).join(" | ");
    await expect(
      page.getByTestId("operator-replay-command-feedback"),
      `no success feedback; flash: ${await flashText()}`,
    ).toBeVisible();
    await expect(page.getByTestId("operator-replay-command-feedback")).toHaveText(
      /Replay command (added|completed)/,
    );
    await expect(page.getByTestId("operator-replay-modal")).toBeHidden();
    await expect(succeeded).toHaveCount(before + 1);
  });
});
